/*
 * A038966  Primes p such that 79 is not a square mod p.
 * https://oeis.org/A038966
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   compute primes p for which 79 is not a quadratic residue modulo
 *            p. The set is generated by enumerating primes and testing the
 *            Legendre/Jacobi symbol (p/79). For p ≡ 1 (mod 4) we require
 *            (p/79) = –1, and for p ≡ 3 (mod 4) we require (p/79) = 1. The
 *            prime 79 is omitted
 * Range:     u8 n <= 29, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   ensure_capacity, jacobi_symbol
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>
#include "../utils/jacobi_symbol.h"
#include "../utils/ensure_capacity.h"

seq_t a(idx_t n)
{
    /* Static state shared between calls */
    static seq_t *seq = NULL;          /* filled terms of the sequence   */
    static size_t seq_len = 0;         /* number of terms currently stored */
    static size_t seq_cap = 0;         /* allocated capacity of seq      */

    static uint64_t *primes = NULL;    /* list of primes found so far     */
    static size_t prime_cnt = 0;       /* number of primes found          */
    static size_t prime_cap = 0;       /* allocated capacity of primes    */
    static uint64_t last_prime = 2;    /* last prime processed            */
    static uint64_t next_candidate = 3;/* next odd number to test         */
    static bool initialized = false;  /* one‑time initialization flag    */

    /* One‑time initialization of supporting arrays */
    if (!initialized) {
        initialized = true;

        /* Allocate space for primes (small initial capacity) */
        ensure_capacity(8, &prime_cap, (void **)&primes, sizeof(uint64_t));
        primes[0] = 2;
        prime_cnt = 1;

        /* Allocate space for sequence (empty at start) */
        ensure_capacity(8, &seq_cap, (void **)&seq, sizeof(seq_t));
    }

    /* Generate terms until we have at least n of them */
    while (seq_len < n) {
        /* ---------------------------------------------
           Find the next prime number after last_prime
        --------------------------------------------- */
        uint64_t cand = last_prime + 1;
        if (cand <= 2) cand = 3;
        if ((cand & 1) == 0) cand++;          /* ensure odd */

        /* Search for the next prime */
        for (;;) {
            /* Trial division using primes already found */
            bool is_prime = true;
            for (size_t i = 0; i < prime_cnt; ++i) {
                uint64_t p = primes[i];
                if (p * p > cand) break;
                if (cand % p == 0) { is_prime = false; break; }
            }

            if (is_prime) {
                /* Store the new prime */
                ensure_capacity(prime_cnt + 1, &prime_cap, (void **)&primes, sizeof(uint64_t));
                primes[prime_cnt++] = cand;
                last_prime = cand;
                next_candidate = last_prime + 1;
                if ((next_candidate & 1) == 0) next_candidate++;
                break;
            }

            cand += 2;  /* test only odd numbers */
        }

        /* Raise sequence if the prime satisfies the condition */
        uint64_t p = last_prime;
        if (p == 79) {
            /* skip the prime that divides 79 – 79 is a square (zero) mod 79 */
        } else {
            int leg = jacobi_symbol(p, 79);   /* Legendre symbol (p/79)  */
            bool include = false;
            if ((p & 3) == 1) {               /* p ≡ 1 (mod 4)   */
                include = (leg == -1);
            } else if ((p & 3) == 3) {         /* p ≡ 3 (mod 4)   */
                include = (leg == 1);
            }
            if (include) {
                ensure_capacity(seq_len + 1, &seq_cap, (void **)&seq, sizeof(seq_t));
                seq[seq_len++] = (seq_t)p;
            }
        }
    }

    return seq[n - 1];
}
